public class DamageCalculator
{
    private readonly IArmorSystem armor;
    private readonly ICriticalHitSystem crit;

    public DamageCalculator(IArmorSystem armor, ICriticalHitSystem crit)
    {
        this.armor = armor;
        this.crit = crit;
    }

    public int CalculateDamage(int baseDamage, DamageType type, TargetInfo target)
    {
        float multiplier = armor.GetDamageMultiplier(target, type);
        bool isCrit = crit.RollForCritical(target);

        int finalDamage = Mathf.RoundToInt(baseDamage * multiplier);
        if (isCrit) finalDamage *= 2;

        return finalDamage;
    }
}

public interface IArmorSystem { float GetDamageMultiplier(TargetInfo target, DamageType type); }
public interface ICriticalHitSystem { bool RollForCritical(TargetInfo target); }
public enum DamageType { Physical, Fire, Ice, Electric }
public struct TargetInfo { public float armorRating; public float level; }

