// ============================================
// PUBLISHER — does not know who listens
// ============================================
public class Enemy : MonoBehaviour, IDamageable
{
    [SerializeField] private int scoreValue = 100;

    public void Die(bool wasHeadshot = false)
    {
        // Publish event — zero knowledge of subscribers
        EventBus<EnemyDiedEvent>.Publish(new EnemyDiedEvent
        {
            Enemy = this,
            Position = transform.position,
            ScoreValue = wasHeadshot ? scoreValue * 2 : scoreValue,
            WasHeadshot = wasHeadshot
        });

        Destroy(gameObject);
    }
}

public interface IDamageable { void Die(bool wasHeadshot = false); }

